    </svg>
);

// --- Types ---

type DemoStep = 
  | 'idle' 
  | 'user_typing' 
  | 'msg_sent' 
  | 'ai_processing' 
  | 'crm_updating' 
  | 'ai_typing' 
  | 'ai_reply' 
  | 'complete';

type Channel = 'whatsapp' | 'instagram';

interface ChatMessage {
    id: string;
    sender: 'user' | 'ai';
    text: string;
    status: 'sent' | 'delivered' | 'read';
}

// --- Component ---

export const InteractiveDemo: React.FC = () => {
    const { t } = useTranslation();
    const [channel, setChannel] = useState<Channel>('whatsapp');
    const [step, setStep] = useState<DemoStep>('idle');
    const [chat, setChat] = useState<ChatMessage[]>([]);
    const [crmData, setCrmData] = useState({ name: '', intent: '', stage: '', tag: '' });

    // Data Config
    const config = {
        whatsapp: {
            user: { name: 'Khalid Al-Manning', avatar: 'Khalid' },
            msg: "Hi, I'm interested in the 4-bedroom villa in The Pearl. Is it still available?",
            reply: "Hello Khalid! Yes, the 4-bedroom villa in The Pearl is available. Would you like to schedule a viewing for this week? 🏡",
            crm: { name: 'Khalid Al-Manning', intent: 'Property Inquiry', stage: 'New Lead', tag: 'High Value' }
        },
        instagram: {
            user: { name: 'Sarah Fashion', avatar: 'Sarah' },
            msg: "Hey! Do you have this summer dress in size M? Need it urgently!",
            reply: "Hi Sarah! ✨ Yes, we have Size M in stock at our Doha Festival City branch. Shall I reserve it for you?",
            crm: { name: 'Sarah Fashion', intent: 'Product Inquiry', stage: 'Urgent', tag: 'Retail' }
        }
    };

    const currentData = config[channel];

    // Animation Sequencer
    useEffect(() => {
        let timer: NodeJS.Timeout;
        const sequence = async () => {
            // Reset
            setChat([]);
            setCrmData({ name: '', intent: '', stage: '', tag: '' });
            setStep('idle');

            await new Promise(r => setTimeout(r, 800));
            setStep('user_typing');

            await new Promise(r => setTimeout(r, 1500));
            setChat([{ id: '1', sender: 'user', text: currentData.msg, status: 'sent' }]);
            setStep('msg_sent');

            await new Promise(r => setTimeout(r, 800));
            setStep('ai_processing'); // Beam animation starts here

            await new Promise(r => setTimeout(r, 1000));
            setStep('crm_updating');

            // CRM Populates
            setCrmData(prev => ({ ...prev, name: currentData.crm.name }));
            await new Promise(r => setTimeout(r, 400));
            setCrmData(prev => ({ ...prev, intent: currentData.crm.intent }));
            await new Promise(r => setTimeout(r, 400));
            setCrmData(prev => ({ ...prev, stage: currentData.crm.stage }));
            await new Promise(r => setTimeout(r, 400));
            setCrmData(prev => ({ ...prev, tag: currentData.crm.tag }));

            await new Promise(r => setTimeout(r, 600));
            setStep('ai_typing');

            await new Promise(r => setTimeout(r, 1800));
            setChat(prev => [
                { ...prev[0], status: 'read' },
                { id: '2', sender: 'ai', text: currentData.reply, status: 'read' }
            ]);
            setStep('ai_reply');

            await new Promise(r => setTimeout(r, 4000));
            setStep('complete'); // Triggers restart via dependency
        };

        sequence();
        return () => clearTimeout(timer);
    }, [channel, step === 'complete']); // Restart when channel changes or sequence completes

    // Styles based on channel
    const isWA = channel === 'whatsapp';
    const bgStyle = isWA 
        ? "bg-[#EFE7DE]" 
        : "bg-white";
    const headerColor = isWA ? "bg-[#008069]" : "bg-white border-b border-gray-100";
    const headerText = isWA ? "text-white" : "text-black";
    const bubbleUser = isWA ? "bg-[#E7FFDB] text-gray-900 rounded-tr-none shadow-sm" : "bg-gray-100 text-black rounded-br-none";
    const bubbleAi = isWA ? "bg-white text-gray-900 rounded-tl-none shadow-sm" : "bg-gradient-to-r from-purple-500 to-pink-500 text-white rounded-bl-none";

    return (
        <div className="w-full flex flex-col items-center">

            {/* Control Toggle */}
            <div className="bg-gray-100/80 dark:bg-zinc-800/80 p-1 rounded-full flex gap-1 mb-12 backdrop-blur-sm border border-gray-200 dark:border-zinc-700">
                {(['whatsapp', 'instagram'] as Channel[]).map((c) => (
                    <button
                        key={c}
                        onClick={() => setChannel(c)}
                        className={cn(
                            "px-6 py-2 rounded-full text-sm font-semibold transition-all duration-300",
                            channel === c 
                                ? "bg-white dark:bg-zinc-900 text-primary shadow-md transform scale-105" 
                                : "text-gray-500 hover:text-gray-900 dark:hover:text-gray-300"
                        )}
                    >
                        {c.charAt(0).toUpperCase() + c.slice(1)}
                    </button>
                ))}
            </div>

            {/* The Stage */}
            <div className="relative w-full max-w-5xl flex flex-col md:flex-row items-center justify-center gap-12 lg:gap-24">

                {/* 1. PHONE MOCKUP */}
                <div className="relative w-[300px] h-[600px] bg-black rounded-[50px] shadow-[0_0_0_12px_#1f1f1f,0_0_0_13px_#333,0_20px_50px_-10px_rgba(0,0,0,0.5)] overflow-hidden transition-transform duration-500 hover:scale-[1.01]">
                    {/* Dynamic Island */}
                    <div className="absolute top-0 left-1/2 -translate-x-1/2 h-[35px] w-[120px] bg-black rounded-b-3xl z-30"></div>

                    {/* Status Bar (Fake) */}
                    <div className={cn("h-14 pt-4 px-6 flex justify-between items-end text-[10px] font-bold z-20 relative", headerText)}>
                        <span>9:41</span>
                        <div className="flex gap-1">
                            <div className="w-3 h-3 bg-current rounded-full opacity-20"></div>
                            <div className="w-3 h-3 bg-current rounded-full opacity-20"></div>
                            <div className="w-4 h-2.5 border border-current rounded-[1px]"></div>
                        </div>
                    </div>

                    {/* App Header */}
                    <div className={cn("h-16 px-4 flex items-center gap-3 z-10 relative transition-colors duration-500", headerColor)}>
                        {isWA && <div className="text-white"><svg width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7"/></svg></div>}
                        <Avatar name={currentData.user.name} className="w-9 h-9 ring-2 ring-white/20" />
                        <div className="flex-1">
                            <p className={cn("text-sm font-bold leading-tight", headerText)}>{currentData.user.name}</p>
                            <p className={cn("text-[10px] opacity-80", headerText)}>Online</p>
                        </div>
                        <div className={cn("flex gap-4 opacity-80", headerText)}>
                             <svg width="20" height="20" fill="currentColor" viewBox="0 0 24 24"><path d="M15.9 14.3H15l-.3-.3c1-1.1 1.6-2.7 1.6-4.3 0-3.7-3-6.7-6.7-6.7S3 6 3 9.7s3 6.7 6.7 6.7c1.6 0 3.2-.6 4.3-1.6l.3.3v.9l5.1 5.1 1.5-1.5-5-5.2zm-6.2 0c-2.6 0-4.6-2.1-4.6-4.6s2.1-4.6 4.6-4.6 4.6 2.1 4.6 4.6-2 4.6-4.6 4.6z"/></svg>
                        </div>
                    </div>

                    {/* Chat Area */}
                    <div className={cn("flex-1 p-4 overflow-y-auto relative transition-colors duration-500 flex flex-col gap-3", bgStyle)}>
                         {isWA && <div className="absolute inset-0 opacity-[0.08] bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] pointer-events-none"></div>}

                         {/* Messages */}
                         {chat.map((msg, i) => (
                             <div key={msg.id} className={cn("relative z-10 flex w-full animate-in", msg.sender === 'user' ? (isWA ? "justify-end" : "justify-start") : (isWA ? "justify-start" : "justify-end"))}>
                                <div className={cn("max-w-[85%] px-3 py-2 text-sm relative", msg.sender === 'user' ? bubbleUser : bubbleAi)}>
                                    {msg.text}
                                    <div className={cn("flex items-center justify-end gap-1 mt-1", isWA ? "opacity-60" : "hidden")}>
                                        <span className="text-[9px]">9:42 AM</span>
                                        {msg.sender === 'user' && msg.status === 'read' && <CheckDoubleIcon className="w-3 h-3 text-blue-500" />}
                                        {msg.sender === 'user' && msg.status !== 'read' && <CheckDoubleIcon className="w-3 h-3 text-gray-500" />}
                                    </div>
                                </div>
                             </div>
                         ))}

                         {/* Typing Indicator */}
                         {(step === 'user_typing' || step === 'ai_typing') && (
                             <div className={cn("relative z-10 flex w-full animate-in", step === 'user_typing' ? (isWA ? "justify-end" : "justify-start") : (isWA ? "justify-start" : "justify-end"))}>
                                 <div className={cn("px-4 py-3 rounded-2xl flex gap-1 items-center", step === 'user_typing' ? bubbleUser : bubbleAi)}>
                                     <div className="w-1.5 h-1.5 bg-current rounded-full opacity-60 animate-bounce-delay-1"></div>
                                     <div className="w-1.5 h-1.5 bg-current rounded-full opacity-60 animate-bounce-delay-2"></div>
                                     <div className="w-1.5 h-1.5 bg-current rounded-full opacity-60 animate-bounce-delay-3"></div>
                                 </div>
                             </div>
                         )}
                    </div>

                    {/* Fake Input */}
                    <div className="h-16 bg-[#F0F2F5] dark:bg-zinc-900 border-t border-gray-200 dark:border-zinc-800 flex items-center px-4 gap-3 z-20">
                        <div className="text-blue-500"><svg width="24" height="24" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4"/></svg></div>
                        <div className="flex-1 h-9 bg-white dark:bg-black rounded-full border border-gray-300 dark:border-zinc-700"></div>
                        <div className="text-blue-500"><svg width="24" height="24" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"/></svg></div>
                    </div>
                </div>

                {/* 2. INTELLIGENCE CONNECTOR (The "Beam") */}
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-0 hidden md:flex items-center justify-center w-[300px]">
                     {/* The Beam Path */}
                     <div className="w-full h-[2px] bg-gradient-to-r from-transparent via-gray-300 to-transparent dark:via-zinc-700 relative overflow-hidden">
                        {/* The Active Energy Pulse */}
                        {(step === 'ai_processing' || step === 'crm_updating' || step === 'ai_typing') && (
                            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-primary to-transparent w-1/2 animate-beam h-full blur-[2px]"></div>
                        )}
                     </div>

                     {/* The "Brain" Node */}
                     <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2">
                        <div className={cn(
                            "w-16 h-16 rounded-full bg-white dark:bg-zinc-900 border border-gray-200 dark:border-zinc-700 shadow-xl flex items-center justify-center transition-all duration-500",
                            (step === 'ai_processing' || step === 'crm_updating') ? "scale-110 border-primary shadow-[0_0_30px_-5px_rgba(var(--primary),0.4)]" : "scale-100"
                        )}>
                            <BrainCircuitIcon className={cn("w-8 h-8 transition-colors duration-300", (step === 'ai_processing' || step === 'crm_updating') ? "text-primary" : "text-gray-400")} />
                        </div>
                     </div>
                </div>

                {/* 3. CRM WIDGET (Glassmorphism) */}
                <div className="w-[340px] z-10 perspective-1000">
                    <div className={cn(
                        "relative bg-white/60 dark:bg-black/60 backdrop-blur-xl border border-white/20 dark:border-white/10 rounded-3xl shadow-2xl p-6 transition-all duration-700",
                        step === 'idle' ? "opacity-50 scale-95 translate-y-4" : "opacity-100 scale-100 translate-y-0"
                    )}>
                        {/* Header */}
                        <div className="flex items-center justify-between mb-8">
                            <div className="flex items-center gap-2">
                                <div className="w-3 h-3 rounded-full bg-red-400"></div>
                                <div className="w-3 h-3 rounded-full bg-yellow-400"></div>
                                <div className="w-3 h-3 rounded-full bg-green-400"></div>
                            </div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground/80">Flowtiva CRM</span>
                        </div>

                        {/* Fields */}
                        <div className="space-y-5">
                            {/* Name Field */}
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider pl-1">Contact</label>
                                <div className="h-12 bg-white/50 dark:bg-zinc-800/50 rounded-xl border border-gray-200/50 dark:border-zinc-700/50 flex items-center px-4 shadow-sm transition-all duration-500 overflow-hidden relative">
                                    {crmData.name ? (
                                        <div className="flex items-center gap-3 animate-in slide-in-from-left-4 fade-in duration-500">
                                            <Avatar name={currentData.user.name} className="w-6 h-6" />
                                            <span className="font-semibold text-sm">{crmData.name}</span>
                                        </div>
                                    ) : <div className="w-1/3 h-2 bg-gray-200 dark:bg-zinc-700 rounded-full animate-pulse"></div>}
                                    {/* Success Flash */}
                                    <div className={cn("absolute inset-0 bg-green-400/10 transition-opacity duration-500", crmData.name ? "opacity-0" : "opacity-0")} /> 
                                </div>
                            </div>

                            {/* Intent Field */}
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider pl-1">Detected Intent</label>
                                <div className="h-12 bg-white/50 dark:bg-zinc-800/50 rounded-xl border border-gray-200/50 dark:border-zinc-700/50 flex items-center px-4 shadow-sm relative overflow-hidden">
                                     {crmData.intent ? (
                                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-md text-xs font-bold bg-primary/10 text-primary animate-in zoom-in-90 fade-in duration-300">
                                            {crmData.intent}
                                        </span>
                                    ) : <div className="w-1/4 h-2 bg-gray-200 dark:bg-zinc-700 rounded-full animate-pulse"></div>}
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                {/* Stage Field */}
                                <div className="space-y-1.5">
                                    <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider pl-1">Stage</label>
                                    <div className="h-12 bg-white/50 dark:bg-zinc-800/50 rounded-xl border border-gray-200/50 dark:border-zinc-700/50 flex items-center px-4 shadow-sm relative overflow-hidden">
                                        {crmData.stage && (
                                            <span className="text-xs font-medium animate-in fade-in duration-300">{crmData.stage}</span>
                                        )}
                                    </div>
                                </div>
                                {/* Tag Field */}
                                <div className="space-y-1.5">
                                    <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider pl-1">Tag</label>
                                    <div className="h-12 bg-white/50 dark:bg-zinc-800/50 rounded-xl border border-gray-200/50 dark:border-zinc-700/50 flex items-center px-4 shadow-sm relative overflow-hidden">
                                        {crmData.tag && (
                                            <span className="text-xs font-medium text-gray-500 animate-in fade-in duration-300">#{crmData.tag}</span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>

                         {/* Status Footer */}
                         <div className="mt-8 pt-4 border-t border-gray-100 dark:border-zinc-800 flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <div className={cn("w-2 h-2 rounded-full", step === 'complete' ? "bg-green-500" : "bg-yellow-500 animate-pulse")}></div>
                                <span className="text-[10px] uppercase font-bold text-muted-foreground">{step === 'complete' ? "Synced" : "Processing"}</span>
                            </div>
                            {isWA ? <WhatsAppIcon className="w-5 h-5 opacity-50 grayscale hover:grayscale-0 transition-all"/> : <InstagramIcon className="w-5 h-5 opacity-50 grayscale hover:grayscale-0 transition-all"/>}
                         </div>
                    </div>
                </div>

            </div>
        </div>
    );
};

