// --- Types ---

type DemoStep = 
  | 'idle' 
  | 'user_typing' 
  | 'msg_sent' 
  | 'ai_processing' 
  | 'crm_updating' 
  | 'ai_typing' 
  | 'ai_reply' 
  | 'complete';

type Channel = 'whatsapp' | 'instagram';

interface ChatMessage {
    id: string;
    sender: 'user' | 'ai';
    text: string;
    status: 'sent' | 'delivered' | 'read';
}

