                         {/* Side Buttons */}
                         <div className="absolute top-32 -left-[8px] h-8 w-[2px] bg-[#333] rounded-l-lg shadow-[-1px_0_2px_0_rgba(0,0,0,0.5)]"></div> {/* Silent */}
                         <div className="absolute top-48 -left-[8px] h-14 w-[2px] bg-[#333] rounded-l-lg shadow-[-1px_0_2px_0_rgba(0,0,0,0.5)]"></div> {/* Vol Up */}
                         <div className="absolute top-64 -left-[8px] h-14 w-[2px] bg-[#333] rounded-l-lg shadow-[-1px_0_2px_0_rgba(0,0,0,0.5)]"></div> {/* Vol Down */}
                         <div className="absolute top-52 -right-[8px] h-20 w-[2px] bg-[#333] rounded-r-lg shadow-[1px_0_2px_0_rgba(0,0,0,0.5)]"></div> {/* Power */}

