                             </div>

                             {/* App Header */}
                            <div className={cn("h-16 px-4 flex items-center gap-3 z-30 relative transition-colors duration-500 border-b border-white/5", headerColor)}>
                                {isWA && <div className="text-white"><svg width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7"/></svg></div>}
                                <Avatar name={currentData.user.name} className="w-9 h-9 ring-2 ring-white/20" />
                                <div className="flex-1">
                                    <p className={cn("text-sm font-bold leading-tight", headerText)}>{currentData.user.name}</p>
                                    <p className={cn("text-[10px] opacity-80", headerText)}>Online</p>
                                </div>
                                <div className={cn("flex gap-4 opacity-80", headerText)}>
                                    <svg width="20" height="20" fill="currentColor" viewBox="0 0 24 24"><path d="M15.9 14.3H15l-.3-.3c1-1.1 1.6-2.7 1.6-4.3 0-3.7-3-6.7-6.7-6.7S3 6 3 9.7s3 6.7 6.7 6.7c1.6 0 3.2-.6 4.3-1.6l.3.3v.9l5.1 5.1 1.5-1.5-5-5.2zm-6.2 0c-2.6 0-4.6-2.1-4.6-4.6s2.1-4.6 4.6-4.6 4.6 2.1 4.6 4.6-2 4.6-4.6 4.6z"/></svg>
                                </div>
                            </div>

                            {/* Chat Area */}
                            <div className={cn("flex-1 p-4 overflow-y-auto relative transition-colors duration-500 flex flex-col gap-3", bgStyle)}>
