// --- Types ---

type DemoStep = 
  | 'idle' 
  | 'user_typing' 
  | 'msg_sent' 
  | 'ai_processing' 
  | 'crm_updating' 
  | 'ai_typing' 
  | 'ai_reply' 
  | 'complete';

type Channel = 'whatsapp' | 'instagram';

interface ChatMessage {
    id: string;
    sender: 'user' | 'ai';
    text: string;
    status: 'sent' | 'delivered' | 'read';
}

// --- Component ---

export const InteractiveDemo: React.FC = () => {
    const { t } = useTranslation();
    const [channel, setChannel] = useState<Channel>('whatsapp');
    const [step, setStep] = useState<DemoStep>('idle');
    const [chat, setChat] = useState<ChatMessage[]>([]);
    const [crmData, setCrmData] = useState({ name: '', intent: '', stage: '', tag: '' });

    // Data Config
    const config = {
        whatsapp: {
            user: { name: 'Khalid Al-Manning', avatar: 'Khalid' },
            msg: "Hi, I'm interested in the 4-bedroom villa in The Pearl. Is it still available?",
            reply: "Hello Khalid! Yes, the 4-bedroom villa in The Pearl is available. Would you like to schedule a viewing for this week? 🏡",
            crm: { name: 'Khalid Al-Manning', intent: 'Property Inquiry', stage: 'New Lead', tag: 'High Value' }
        },
        instagram: {
            user: { name: 'Sarah Fashion', avatar: 'Sarah' },
            msg: "Hey! Do you have this summer dress in size M? Need it urgently!",
            reply: "Hi Sarah! ✨ Yes, we have Size M in stock at our Doha Festival City branch. Shall I reserve it for you?",
            crm: { name: 'Sarah Fashion', intent: 'Product Inquiry', stage: 'Urgent', tag: 'Retail' }
        }
    };

    const currentData = config[channel];

    // Animation Sequencer
    useEffect(() => {
        let timer: any;
        const sequence = async () => {
            // Reset
            setChat([]);
            setCrmData({ name: '', intent: '', stage: '', tag: '' });
            setStep('idle');

            await new Promise(r => setTimeout(r, 800));
            setStep('user_typing');

            await new Promise(r => setTimeout(r, 1500));
            setChat([{ id: '1', sender: 'user', text: currentData.msg, status: 'sent' }]);
            setStep('msg_sent');

            await new Promise(r => setTimeout(r, 800));
            setStep('ai_processing'); // Beam animation starts here

            await new Promise(r => setTimeout(r, 1000));
            setStep('crm_updating');

            // CRM Populates
            setCrmData(prev => ({ ...prev, name: currentData.crm.name }));
            await new Promise(r => setTimeout(r, 400));
            setCrmData(prev => ({ ...prev, intent: currentData.crm.intent }));
            await new Promise(r => setTimeout(r, 400));
            setCrmData(prev => ({ ...prev, stage: currentData.crm.stage }));
            await new Promise(r => setTimeout(r, 400));
            setCrmData(prev => ({ ...prev, tag: currentData.crm.tag }));

            await new Promise(r => setTimeout(r, 600));
            setStep('ai_typing');

            await new Promise(r => setTimeout(r, 1800));
            setChat(prev => [
                { ...prev[0], status: 'read' },
                { id: '2', sender: 'ai', text: currentData.reply, status: 'read' }
            ]);
            setStep('ai_reply');

            await new Promise(r => setTimeout(r, 4000));
            setStep('complete'); // Triggers restart via dependency
        };

        sequence();
        return () => clearTimeout(timer);
    }, [channel, step === 'complete']); // Restart when channel changes or sequence completes

