                {(['whatsapp', 'instagram'] as Channel[]).map((c) => (
                    <button
                        key={c}
                        onClick={() => setChannel(c)}
                        className={cn(
                            "px-6 py-2 rounded-full text-sm font-semibold transition-all duration-300",
                            channel === c 
                                ? "bg-white dark:bg-zinc-900 text-primary shadow-md transform scale-105" 
                                : "text-gray-500 hover:text-gray-900 dark:hover:text-gray-300"
                        )}
                    >
                        {c.charAt(0).toUpperCase() + c.slice(1)}
                    </button>
                ))}
            </div>

            {/* The Stage */}
            <div className="relative w-full max-w-5xl flex flex-col md:flex-row items-center justify-center gap-12 lg:gap-24">

                {/* 1. PHONE MOCKUP */}
                {/* Rebuilt structure based on the provided reference code concepts */}
                <div className="relative group perspective-1000">
                    {/* Shadow & Glow */}
                    <div className="absolute -inset-1 bg-gradient-to-b from-gray-600 to-gray-900 rounded-[50px] opacity-30 blur-xl group-hover:opacity-40 transition duration-1000"></div>

                    {/* Main Chassis (.iphone from ref) */}
                    <div className="relative w-[320px] h-[650px] bg-[#050007] rounded-[55px] border-[8px] border-[#1f2025] shadow-[0_0_0_4px_#515056] z-10 transition-transform duration-500 hover:rotate-y-1">

                        {/* Antenna Bands (.dash) */}
                        <div className="absolute top-[80px] -left-[10px] w-[2px] h-[6px] bg-[#67666b] z-20"></div>
                        <div className="absolute bottom-[80px] -left-[10px] w-[2px] h-[6px] bg-[#67666b] z-20"></div>
                        <div className="absolute top-[80px] -right-[10px] w-[2px] h-[6px] bg-[#67666b] z-20"></div>
                        <div className="absolute bottom-[80px] -right-[10px] w-[2px] h-[6px] bg-[#67666b] z-20"></div>

                        {/* Physical Buttons (.side) */}
                        {/* Silent Switch */}
                        <div className="absolute top-[100px] -left-[12px] h-[28px] w-[4px] bg-[#2a2a2a] rounded-l-md shadow-[-1px_0_2px_rgba(0,0,0,0.6)]"></div>
                        {/* Volume Up */}
                        <div className="absolute top-[150px] -left-[12px] h-[50px] w-[4px] bg-[#2a2a2a] rounded-l-md shadow-[-1px_0_2px_rgba(0,0,0,0.6)] cursor-pointer active:translate-x-[1px]"></div>
                        {/* Volume Down */}
                        <div className="absolute top-[215px] -left-[12px] h-[50px] w-[4px] bg-[#2a2a2a] rounded-l-md shadow-[-1px_0_2px_rgba(0,0,0,0.6)] cursor-pointer active:translate-x-[1px]"></div>
