                                 <div className="w-1.5 h-1.5 rounded-full bg-[#101010] opacity-60"></div>
                             </div>

                             {/* Status Bar (.top) */}
                             <div className={cn("h-11 pt-3 px-6 flex justify-between items-center text-[12px] font-bold z-40 select-none", headerText)}>
                                <span className="pl-1">9:41</span>
                                <div className="flex gap-1.5 items-center pr-1 opacity-90">
                                     <IOSSignalIcon className="w-3.5 h-3.5" />
                                     <IOSWifiIcon className="w-3.5 h-3.5" />
                                     <IOSBatteryIcon className="w-5 h-3.5" />
                                </div>
                             </div>

                             {/* App Header */}
                            <div className={cn("h-16 px-3 flex items-center gap-2 z-30 relative transition-colors duration-500 border-b border-white/5", headerColor)}>
                                {isWA && <div className="text-white -ml-1"><svg width="24" height="24" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7"/></svg></div>}
                                <Avatar name={currentData.user.name} className="w-9 h-9 ring-1 ring-white/20" />
                                <div className="flex-1 min-w-0">
                                    <p className={cn("text-sm font-bold leading-tight truncate", headerText)}>{currentData.user.name}</p>
                                    <p className={cn("text-[10px] opacity-80 truncate", headerText)}>Online</p>
                                </div>
                                <div className={cn("flex gap-3 opacity-90", headerText)}>
                                    <svg width="22" height="22" fill="currentColor" viewBox="0 0 24 24"><path d="M15.9 14.3H15l-.3-.3c1-1.1 1.6-2.7 1.6-4.3 0-3.7-3-6.7-6.7-6.7S3 6 3 9.7s3 6.7 6.7 6.7c1.6 0 3.2-.6 4.3-1.6l.3.3v.9l5.1 5.1 1.5-1.5-5-5.2zm-6.2 0c-2.6 0-4.6-2.1-4.6-4.6s2.1-4.6 4.6-4.6 4.6 2.1 4.6 4.6-2 4.6-4.6 4.6z"/></svg>
                                </div>
