                                        <div className={cn("max-w-[85%] px-3 py-1.5 text-[13px] relative shadow-sm", msg.sender === 'user' ? bubbleUser : bubbleAi)}>
                                            {msg.text}
                                            <div className={cn("flex items-center justify-end gap-0.5 mt-0.5", isWA ? "opacity-60" : "hidden")}>
                                                <span className="text-[9px]">9:42 AM</span>
                                                {msg.sender === 'user' && msg.status === 'read' && <CheckDoubleIcon className="w-3 h-3 text-[#53bdeb]" />}
                                                {msg.sender === 'user' && msg.status !== 'read' && <CheckDoubleIcon className="w-3 h-3 text-gray-500" />}
                                            </div>
                                        </div>
                                    </div>
                                ))}

                                {/* Typing Indicator */}
                                {(step === 'user_typing' || step === 'ai_typing') && (
                                    <div className={cn("relative z-10 flex w-full animate-in", step === 'user_typing' ? (isWA ? "justify-end" : "justify-start") : (isWA ? "justify-start" : "justify-end"))}>
                                        <div className={cn("px-3 py-2.5 rounded-2xl flex gap-1 items-center shadow-sm", step === 'user_typing' ? bubbleUser : bubbleAi)}>
                                            <div className="w-1.5 h-1.5 bg-current rounded-full opacity-60 animate-bounce-delay-1"></div>
                                            <div className="w-1.5 h-1.5 bg-current rounded-full opacity-60 animate-bounce-delay-2"></div>
                                            <div className="w-1.5 h-1.5 bg-current rounded-full opacity-60 animate-bounce-delay-3"></div>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Input Area */}
                            <div className="h-[70px] bg-[#F0F2F5] dark:bg-zinc-900 border-t border-gray-200 dark:border-zinc-800 flex items-start pt-3 px-3 gap-2 z-20">
                                <div className="text-[#007aff] mt-1"><svg width="24" height="24" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4"/></svg></div>
                                <div className="flex-1 h-8 bg-white dark:bg-black rounded-full border border-gray-300 dark:border-zinc-700"></div>
