interface MessageComposerProps {
    onSendMessage: (text: string, imageBase64: string | null) => void;
    isSending: boolean;
}

const MessageComposer: React.FC<MessageComposerProps> = ({ onSendMessage, isSending }) => {
    const { t } = useTranslation();
    const [text, setText] = useState('');
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    const handleSend = () => { 
        if (!text.trim() || isSending) return; 
        onSendMessage(text, null); 
        setText(''); 
        if (textareaRef.current) textareaRef.current.style.height = 'auto';
    };

    // Auto-resize textarea
    useEffect(() => {
        if (textareaRef.current) {
            textareaRef.current.style.height = 'auto';
            textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
        }
    }, [text]);

    return (
        <footer className="px-4 py-3 bg-[#F0F2F5] dark:bg-[#202C33] flex-shrink-0 flex items-end gap-2 border-l border-gray-200 dark:border-gray-800">
             <Button variant="ghost" size="icon" className="h-10 w-10 text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full mb-0.5">
                <Icons.Icon id="smiley" className="w-6 h-6"/>
            </Button>
            <Button variant="ghost" size="icon" className="h-10 w-10 text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full mb-0.5">
                <Icons.Icon id="attach" className="w-6 h-6"/>
            </Button>

            <div className="flex-1 bg-white dark:bg-[#2A3942] rounded-lg border border-transparent focus-within:border-white transition-all shadow-sm flex items-center min-h-[42px] px-3 py-1">
                <Textarea
                    ref={textareaRef}
                    placeholder={t('whatsapp.messagePane.writeMessage')}
                    value={text}
                    onChange={(e) => setText(e.target.value)}
                    onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); }}}
                    className="flex-1 resize-none bg-transparent border-none focus-visible:ring-0 text-sm text-gray-800 dark:text-gray-100 placeholder:text-gray-500 min-h-[24px] py-1 max-h-32"
                    rows={1}
                    disabled={isSending}
                />
            </div>

            {text.trim() ? (
                <Button size="icon" onClick={handleSend} disabled={isSending} className="h-10 w-10 rounded-full bg-[#00A884] hover:bg-[#008f6f] text-white shadow-sm mb-0.5">
                    <Icons.Icon id="send" className="w-5 h-5 ml-0.5"/>
                </Button>
            ) : (
                <Button variant="ghost" size="icon" className="h-10 w-10 text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full mb-0.5">
                     <Icons.Icon id="microphone" className="w-6 h-6"/>
                </Button>
            )}
        </footer>
    );
};

