interface MessagePaneProps {
    instance: WhatsAppInstance;
    contact: WhatsAppContact;
    messages: WhatsAppMessage[];
    isLoading: boolean;
    onSendMessage: (text: string, imageBase64: string | null) => void;
    isSending: boolean;
    onLoadMore: () => void;
    hasMore: boolean;
    isLoadingMore: boolean;
    error: string | null;
    loadMoreError: string | null;
    onBack: () => void;
    suggestedTags: string[] | null;
    onSaveSuggestedTags: (tagsToSave: string[]) => void;
    onDismissSuggestions: () => void;
    onToggleDetailsPanel: () => void;
    isDetailsPanelOpen: boolean;
}

export const MessagePane: React.FC<MessagePaneProps> = ({ 
    instance,
    contact, 
    messages, 
    isLoading, 
    onSendMessage, 
    isSending, 
    onLoadMore, 
    hasMore, 
    isLoadingMore, 
    error, 
    loadMoreError, 
    onBack,
    suggestedTags,
    onSaveSuggestedTags,
    onDismissSuggestions,
    onToggleDetailsPanel,
    isDetailsPanelOpen
}) => {
    const { t } = useTranslation();
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const prevScrollHeightRef = useRef(0);
    const shouldAutoScrollRef = useRef(true);

    const handleScroll = useCallback(() => {
        const container = scrollContainerRef.current;
        if (!container) return;

        const isNearBottom = container.scrollHeight - container.scrollTop - container.clientHeight < 150;
        shouldAutoScrollRef.current = isNearBottom;

        if (container.scrollTop < 50 && hasMore && !isLoadingMore) {
            prevScrollHeightRef.current = container.scrollHeight;
            onLoadMore();
        }
    }, [hasMore, isLoadingMore, onLoadMore]);

    useEffect(() => {
        shouldAutoScrollRef.current = true;
    }, [contact]);

    useEffect(() => {
        const container = scrollContainerRef.current;
        container?.addEventListener('scroll', handleScroll);
        return () => container?.removeEventListener('scroll', handleScroll);
    }, [handleScroll]);

    useLayoutEffect(() => {
        const container = scrollContainerRef.current;
        if (!container) return;

        const didLoadMore = prevScrollHeightRef.current > 0;

        if (didLoadMore) {
            container.scrollTop = container.scrollHeight - prevScrollHeightRef.current;
            prevScrollHeightRef.current = 0;
        } else if (shouldAutoScrollRef.current) {
            container.scrollTo({ top: container.scrollHeight, behavior: "auto" });
        }
    }, [messages]);

    const renderContent = () => {
        if (isLoading) return <MessagePaneSkeleton />;
        if (error) return (
            <div className="flex justify-center items-center h-full text-center p-4 z-10 relative">
                <div className="text-status-red bg-white/90 p-4 rounded-lg shadow-sm">
                    <p className="font-semibold">{t('common.error')}</p>
                    <p className="text-sm mt-1">{t('common.errorWithMessage', { message: error })}</p>
                </div>
            </div>
        );
        return (
            <div className="space-y-1 relative z-10 px-4 md:px-16 lg:px-24">
                {messages.map(msg => <ChatMessage key={msg.id} message={msg} />)}
            </div>
        );
    };

    return (
        <div className="flex-1 flex flex-col h-full bg-[#EFE7DE] dark:bg-[#0B141A] relative min-w-0">
            {/* Background Pattern */}
            <div className="absolute inset-0 opacity-[0.06] bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] pointer-events-none"></div>

            <header className="h-[59px] px-4 border-b border-gray-200 dark:border-gray-800 flex-shrink-0 flex items-center gap-3 bg-[#F0F2F5] dark:bg-[#202C33] relative z-20">
                <button onClick={onBack} className="md:hidden p-2 text-gray-600 dark:text-gray-300 rounded-full hover:bg-black/10 dark:hover:bg-white/10 -ml-2">
                    <Icons.Icon id="back" className="h-5 w-5"/>
                </button>
                <Avatar name={contact.contact_name} className="w-10 h-10 cursor-pointer" />
                <div className="flex-1 min-w-0 cursor-pointer" onClick={onToggleDetailsPanel}>
                     <h3 className="font-semibold text-gray-900 dark:text-gray-100 truncate text-base">{contact.contact_name}</h3>
                     <p className="text-xs text-gray-500 dark:text-gray-400 truncate">{t('whatsapp.messagePane.online')}</p>
                </div>
                <div className="flex items-center gap-2 text-gray-600 dark:text-gray-300">
                    <Button variant="ghost" size="icon" className="h-10 w-10 rounded-full hover:bg-black/5"><Icons.Icon id="search" className="h-5 w-5" /></Button>
                    <Button variant="ghost" size="icon" className={`h-10 w-10 rounded-full hover:bg-black/5 ${isDetailsPanelOpen ? 'bg-black/10 dark:bg-white/10' : ''}`} onClick={onToggleDetailsPanel}>
                        <Icons.Icon id="details" className="h-5 w-5" />
                    </Button>
                </div>
            </header>

            <div ref={scrollContainerRef} className="flex-1 overflow-y-auto py-2 relative scroll-smooth">
                {loadMoreError && (
                    <div className="text-center my-4 relative z-10"><span className="text-xs bg-white/80 dark:bg-black/60 px-2 py-1 rounded text-status-red">{loadMoreError}</span></div>
                )}
                {isLoadingMore && (
                    <div className="flex justify-center my-4 relative z-10"><span className="text-gray-500 bg-white/80 dark:bg-black/60 px-3 py-1 rounded-full text-xs shadow-sm uppercase tracking-wide font-medium">{t('whatsapp.messagePane.loadingMore')}</span></div>
                )}
                {!hasMore && messages.length > 0 && !isLoadingMore && (
                    <div className="text-center my-6 relative z-10">
                        <span className="text-gray-500 dark:text-gray-400 bg-[#E1F3FB] dark:bg-[#1C2A32] px-4 py-1.5 rounded-lg text-xs font-medium shadow-sm">
                            {t('whatsapp.messagePane.beginning')}
                        </span>
                    </div>
                )}
                {renderContent()}
            </div>

            {/* Suggested Tags (AI) */}
            {suggestedTags && suggestedTags.length > 0 && (
                <div className="bg-[#F0F2F5] dark:bg-[#202C33] px-4 py-2 border-t border-gray-200 dark:border-gray-800 flex items-center justify-between z-20 animate-in slide-in-from-bottom-2">
                    <div className="flex items-center gap-2 overflow-x-auto no-scrollbar">
                         <span className="text-xs font-bold text-gray-500 uppercase tracking-wide whitespace-nowrap">AI Suggests:</span>
                        {suggestedTags.map(tag => (
                            <span key={tag} className="text-xs bg-white dark:bg-[#111B21] border border-gray-300 dark:border-gray-700 px-2 py-0.5 rounded-full whitespace-nowrap">{tag}</span>
                        ))}
                    </div>
                    <div className="flex gap-2 ml-4">
                        <Button size="sm" variant="ghost" onClick={onDismissSuggestions} className="h-7 text-xs">{t('whatsapp.tagSuggestions.dismiss')}</Button>
                        <Button size="sm" onClick={() => onSaveSuggestedTags(suggestedTags)} className="h-7 text-xs bg-[#00A884] hover:bg-[#008f6f] text-white border-none">{t('whatsapp.tagSuggestions.save', { count: suggestedTags.length })}</Button>
                    </div>
                </div>
            )}

            <div className="relative z-20">
                <MessageComposer onSendMessage={onSendMessage} isSending={isSending} />
            </div>
        </div>
    );
};

