                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Icons.Icon id="search" className="h-4 w-4 text-gray-500" />
                    </div>
                    <Input 
                        placeholder={t('whatsapp.contactList.search')} 
                        value={searchTerm} 
                        onChange={(e) => setSearchTerm(e.target.value)} 
                        className="w-full pl-10 pr-3 h-9 bg-[#F0F2F5] dark:bg-[#202C33] border-none rounded-lg text-sm focus:ring-0 placeholder:text-gray-500" 
                    />
                </div>
            </div>

            {/* List */}
            <div className="flex-1 overflow-y-auto">
                {isLoading ? (
                    <ContactListSkeleton />
                ) : error ? (
                    <div className="p-6 text-center text-sm text-red-500">
                        <p>{error}</p>
                    </div>
                ) : contacts.length === 0 ? (
                    <div className="p-8 text-center text-sm text-gray-500">
                        <p>{t('whatsapp.contactList.noConversations')}</p>
                    </div>
                ) : filteredContacts.length === 0 ? (
                    <div className="p-8 text-center text-sm text-gray-500">
                        <p>{t('whatsapp.contactList.noContactsFound')}</p>
                    </div>
                ) : (
                    <ul className="divide-y divide-transparent">
                        {filteredContacts.map(contact => (
                            <ContactListItem 
                                key={contact.contact_name} 
                                contact={contact} 
                                isSelected={selectedContactName === contact.contact_name} 
                                onSelectContact={onSelectContact} 
                                t={t} 
                            />
                        ))}
                    </ul>
                )}
            </div>
        </div>
    );
};

