// --- Types ---

type DemoStep = 
  | 'idle' 
  | 'user_typing' 
  | 'msg_sent' 
  | 'ai_processing' 
  | 'crm_updating' 
  | 'ai_typing' 
  | 'ai_reply' 
  | 'complete';

type Channel = 'whatsapp' | 'instagram';

interface ChatMessage {
    id: string;
    sender: 'user' | 'ai';
    text: string;
    status: 'sent' | 'delivered' | 'read';
}

// --- Component ---

export const InteractiveDemo: React.FC = () => {
    const { t } = useTranslation();
    const [channel, setChannel] = useState<Channel>('whatsapp');
    const [step, setStep] = useState<DemoStep>('idle');
    const [chat, setChat] = useState<ChatMessage[]>([]);
    const [crmData, setCrmData] = useState({ name: '', intent: '', stage: '', tag: '' });

    // Data Config
    const config = {
        whatsapp: {
            user: { name: 'Khalid Al-Manning', avatar: 'Khalid' },
            msg: "Hi, I'm interested in the 4-bedroom villa in The Pearl. Is it still available?",
            reply: "Hello Khalid! Yes, the 4-bedroom villa in The Pearl is available. Would you like to schedule a viewing for this week? 🏡",
            crm: { name: 'Khalid Al-Manning', intent: 'Property Inquiry', stage: 'New Lead', tag: 'High Value' }
        },
        instagram: {
            user: { name: 'Sarah Fashion', avatar: 'Sarah' },
            msg: "Hey! Do you have this summer dress in size M? Need it urgently!",
            reply: "Hi Sarah! ✨ Yes, we have Size M in stock at our Doha Festival City branch. Shall I reserve it for you?",
            crm: { name: 'Sarah Fashion', intent: 'Product Inquiry', stage: 'Urgent', tag: 'Retail' }
        }
    };

    const currentData = config[channel];

    // Animation Sequencer
    useEffect(() => {
        let timer: any;
        const sequence = async () => {
            // Reset
            setChat([]);
            setCrmData({ name: '', intent: '', stage: '', tag: '' });
            setStep('idle');

            await new Promise(r => setTimeout(r, 800));
            setStep('user_typing');

            await new Promise(r => setTimeout(r, 1500));
            setChat([{ id: '1', sender: 'user', text: currentData.msg, status: 'sent' }]);
            setStep('msg_sent');

            await new Promise(r => setTimeout(r, 800));
            setStep('ai_processing'); // Beam animation starts here

            await new Promise(r => setTimeout(r, 1000));
            setStep('crm_updating');

            // CRM Populates
            setCrmData(prev => ({ ...prev, name: currentData.crm.name }));
            await new Promise(r => setTimeout(r, 400));
            setCrmData(prev => ({ ...prev, intent: currentData.crm.intent }));
            await new Promise(r => setTimeout(r, 400));
            setCrmData(prev => ({ ...prev, stage: currentData.crm.stage }));
            await new Promise(r => setTimeout(r, 400));
            setCrmData(prev => ({ ...prev, tag: currentData.crm.tag }));

            await new Promise(r => setTimeout(r, 600));
            setStep('ai_typing');

            await new Promise(r => setTimeout(r, 1800));
            setChat(prev => [
                { ...prev[0], status: 'read' },
                { id: '2', sender: 'ai', text: currentData.reply, status: 'read' }
            ]);
            setStep('ai_reply');

            await new Promise(r => setTimeout(r, 4000));
            setStep('complete'); // Triggers restart via dependency
        };

        sequence();
        return () => clearTimeout(timer);
    }, [channel, step === 'complete']); // Restart when channel changes or sequence completes

    // Styles based on channel
    const isWA = channel === 'whatsapp';
    const bgStyle = isWA 
        ? "bg-[#EFE7DE]" 
        : "bg-white";
    const headerColor = isWA ? "bg-[#008069]" : "bg-white border-b border-gray-100";
    const headerText = isWA ? "text-white" : "text-black";
    const bubbleUser = isWA ? "bg-[#E7FFDB] text-gray-900 rounded-tr-none shadow-sm" : "bg-gray-100 text-black rounded-br-none";
    const bubbleAi = isWA ? "bg-white text-gray-900 rounded-tl-none shadow-sm" : "bg-gradient-to-r from-purple-500 to-pink-500 text-white rounded-bl-none";

    return (
        <div className="w-full flex flex-col items-center">
            <style>{`
                /* iPhone 12 CSS Recreation */
                .iphone-chassis {
                    width: 320px;
                    height: 640px;
                    border-radius: 45px;
                    position: relative;
                    transition: ease all 0.5s;
                    box-shadow: 0 20px 40px -10px rgba(0,0,0,0.5);
                }
                .iphone-border {
                    display: flex;
                    flex-direction: row;
                    flex-wrap: wrap;
                    align-items: center;
                    justify-content: center;
                    align-content: center;
                    height: 100%;
                    width: 100%;
                    background-color: #152839;
                    border: 1px solid rgba(255, 255, 255, 0.6);
                    box-shadow: inset 0 0 3px 1px #fff;
                    border-radius: 45px;
                    position: relative;
                }
                /* Antenna Bands */
                .iphone-border:before, .iphone-border:after {
                    content: "";
                    position: absolute;
                    top: 65px;
                    background-color: rgba(255, 255, 255, 0.1);
                    width: 7px;
                    height: 6px;
                    z-index: 1;
                }
                .iphone-border:before { left: 0px; }
                .iphone-border:after { right: 0px; }

                .iphone-buttons:before, .iphone-buttons:after {
                    content: "";
                    position: absolute;
                    bottom: 65px;
                    background-color: rgba(255, 255, 255, 0.1);
                    width: 7px;
                    height: 6px;
                    z-index: 1;
                }
                .iphone-buttons:before { left: 0px; }
                .iphone-buttons:after { right: 0px; }

                /* Buttons */
                .iphone-buttons > * {
                    position: absolute;
                    left: -3px;
                    width: 3px;
                    background: linear-gradient(90deg, transparent, #152839);
                    border-radius: 20px 10px 10px 20px;
                }
                .iphone-buttons .btn-power {
                    top: 160px;
                    right: -3px;
                    left: auto;
                    height: 80px;
                    background: linear-gradient(90deg, #152839, transparent);
                    border-radius: 10px 20px 20px 10px;
                }
                .iphone-buttons .btn-switch {
                    top: 100px;
                    height: 25px;
                }
                .iphone-buttons .btn-vol-up {
                    top: 150px;
                    height: 45px;
                }
                .iphone-buttons .btn-vol-down {
                    top: 210px;
                    height: 45px;
                }

                /* Inner Bezel */
                .iphone-bezel {
                    display: flex;
                    flex-direction: row;
                    flex-wrap: wrap;
                    align-items: center;
                    justify-content: center;
                    align-content: center;
                    width: calc(100% - 14px);
                    height: calc(100% - 14px);
                    border-radius: 40px;
                    background-color: #000;
                    position: relative;
                    overflow: hidden;
                }
                .iphone-bezel:after {
                    content: "";
                    position: absolute;
                    width: 100%;
                    height: 100%;
                    border-radius: 40px;
                    border: 7px solid #000;
                    box-sizing: border-box;
                    pointer-events: none;
                    z-index: 100;
                }

                /* Notch */
                .iphone-notch {
                    display: flex;
                    flex-direction: row;
                    flex-wrap: wrap;
                    align-items: center;
                    justify-content: center;
                    align-content: center;
                    position: absolute;
                    top: 0;
                    width: 150px;
                    height: 32px;
                    border-bottom-left-radius: 17px;
                    border-bottom-right-radius: 17px;
                    background-color: #000;
                    z-index: 100;
                }
                .iphone-notch:before, .iphone-notch:after {
                    content: "";
                    position: absolute;
                    top: 0;
                    width: 10px;
                    height: 10px;
                    border-radius: 50%;
                    border: 7px solid transparent;
                }
                .iphone-notch:before {
                    left: -17px;
                    border-right-color: #000;
                    transform: rotate(-50deg);
                }
                .iphone-notch:after {
                    right: -17px;
                    border-left-color: #000;
                    transform: rotate(50deg);
                }
                .iphone-speaker {
                    width: 40px;
                    height: 4px;
                    border-radius: 20px;
                    background-color: #1b1b1b;
                    border: 0.7px solid #171717;
                    box-shadow: inset 0px -0.3px 1px 0px #8c8c8c;
                    margin-right: 15px;
                }
                .iphone-camera {
                    width: 14px;
                    height: 14px;
                    border-radius: 50%;
                    background-color: #1b1b1b;
                    position: relative;
                }
                .iphone-camera:before {
                    content: "";
                    position: absolute;
                    width: calc(100% - 4px);
                    height: calc(100% - 4px);
                    background: radial-gradient(#000, #152839 60%);
                    border-radius: 50%;
                    top: 2px; left: 2px;
                }
                .iphone-camera:after {
                    content: "";
                    position: absolute;
                    width: 4px;
                    height: 4px;
                    background-color: rgba(255, 255, 255, 0.1);
                    border-radius: 50%;
                    top: 4px; right: 4px;
                }

                /* Screen */
                .iphone-screen {
                    width: calc(100% - 14px);
                    height: calc(100% - 14px);
                    border-radius: 32px;
                    background-color: #fff;
                    position: relative;
                    overflow: hidden;
                    display: flex;
                    flex-direction: column;
                }
            `}</style>

            {/* Control Toggle */}
            <div className="bg-gray-100/80 dark:bg-zinc-800/80 p-1 rounded-full flex gap-1 mb-12 backdrop-blur-sm border border-gray-200 dark:border-zinc-700">
                {(['whatsapp', 'instagram'] as Channel[]).map((c) => (
                    <button
                        key={c}
                        onClick={() => setChannel(c)}
                        className={cn(
                            "px-6 py-2 rounded-full text-sm font-semibold transition-all duration-300",
                            channel === c 
                                ? "bg-white dark:bg-zinc-900 text-primary shadow-md transform scale-105" 
                                : "text-gray-500 hover:text-gray-900 dark:hover:text-gray-300"
                        )}
                    >
                        {c.charAt(0).toUpperCase() + c.slice(1)}
                    </button>
                ))}
            </div>

            {/* The Stage */}
            <div className="relative w-full max-w-5xl flex flex-col md:flex-row items-center justify-center gap-12 lg:gap-24">

                {/* 1. PHONE MOCKUP */}
                <div className="iphone-chassis group perspective-1000">
                    <div className="iphone-border">
                        <div className="iphone-buttons">
                            <div className="btn-switch"></div>
