                        <div className="iphone-bezel">
                            <div className="iphone-notch">
                                <div className="iphone-speaker"></div>
                                <div className="iphone-camera"></div>
                            </div>

                            <div className="iphone-screen">
                                {/* Status Bar */}
                                <div className={cn("h-11 pt-4 px-6 flex justify-between items-center text-[12px] font-bold z-40 select-none", headerText)}>
                                    <span className="pl-1">9:41</span>
                                    <div className="flex gap-1.5 items-center pr-1 opacity-90">
                                        <IOSSignalIcon className="w-3.5 h-3.5" />
                                        <IOSWifiIcon className="w-3.5 h-3.5" />
                                        <IOSBatteryIcon className="w-5 h-3.5" />
